DATA = {'en': EN, 'ru': RU}


def _base(s):
    return '/almaty-travel-review' if '/almaty-travel-review/' in s else ''


def make_page(tpl, lang, set_meta):
    d = DATA[lang]
    s = tpl.replace('pages/15.html', 'offer/').replace('/summer/%s/offer/' % lang, '/summer/%s/' % lang)
    s = set_meta(s, d['title'], d['desc'])
    s = re.sub(r'<meta name="keywords" content="[^"]*">', '', s)
    s = re.sub(r'<script type="application/ld\+json">.*?</script>', '', s, flags=re.S)
    b = _base(s)
    main = ('<div class="main_container">%s<nav class="almaty-breadcrumbs" aria-label="Breadcrumb"><a href="%s/%s/">%s</a> / <span>%s</span></nav>'
            '<h1>%s</h1><div class="offer-text">%s</div></div>' % (MARK, b, lang, 'Home' if lang == 'en' else 'Главная', d['crumb'], d['h1'], d['body'].strip()))
    s = re.sub(r'<div class="main_container">.*?(?=\s*<div id="center_footer")', lambda m: main, s, count=1, flags=re.S)
    return s


def footer_link(s, lang):
    if 'id="bottom_menu"' not in s or '/offer/">' in s.split('id="bottom_menu"', 1)[1].split('</div>', 1)[0]:
        return s
    b = _base(s)
    link = ' \xa0\xa0\xa0 <a href="%s/%s/offer/">%s</a>' % (b, lang, DATA[lang]['link'])
    return re.sub(r'(<div id="bottom_menu">.*?)(</div>)', lambda m: m.group(1) + link + m.group(2), s, count=1, flags=re.S)


def apply(pages, lang_of, set_meta):
    for lang in ('en', 'ru'):
        tpl = pages.get('%s/pages/15.html' % lang)
        if tpl:
            pages['%s/offer/index.html' % lang] = make_page(tpl, lang, set_meta)
    for rel in list(pages):
        pages[rel] = footer_link(pages[rel], lang_of(rel))
    return pages
